            assert run(tool, repo, 'agent-guide') == text
            texts.append(text)
            for prohibited in ('FIRST action', 'SEARCH FIRST', 'command -v', 'setup.json', 'if Brain is installed', 'entire graph version', 'entire brain version'):
                assert prohibited not in text
        assert len(set(texts)) == 1
        for name in ('AGENTS.md', 'CLAUDE.md'):
            assert (repo / name).read_text().startswith('User rules: preserve these bytes.\n')

    for first in ('graph', 'brain'):
        repo = root / first
        repo.mkdir()
        for name in ('AGENTS.md', 'CLAUDE.md'):
            (repo / name).write_text('User rules: preserve these bytes.\n')
        run(first, repo, 'init-agents')
        check(repo, [first])
        standalone = (repo / '.entire' / (first + '-agent.md')).read_text()
        assert ('entire brain brief' in standalone) == (first == 'brain')
        second = 'brain' if first == 'graph' else 'graph'
        run(second, repo, 'init-agents')
        check(repo, ['graph', 'brain'])
        assert 'redundant Graph query' in (repo / '.entire/graph-agent.md').read_text()
        before = snapshot(repo)
        for tool in (first, second, first):
            run(tool, repo, 'init-agents')
            assert snapshot(repo) == before
            check(repo, ['graph', 'brain'])
        (repo / '.entire/graph-agent.md').unlink()
        run('brain', repo, 'init-agents')
        check(repo, ['brain'])
        assert '# Entire Brain coding-agent guide' in (repo / '.entire/brain-agent.md').read_text()

    repo = root / 'setup-record'
    repo.mkdir()
    subprocess.run(['git', 'init', '-q', str(repo)], env=env, check=True)
    subprocess.run(['git', '-C', str(repo), 'remote', 'add', 'origin', 'https://github.com/test/coordination'], env=env, check=True)
    setup = Path(env['XDG_STATE_HOME']) / 'entire/repos/gh/test/coordination/setup.json'
    setup.parent.mkdir(parents=True)
    setup.write_text('{"schema_version":1,"updated_at":"2000-01-01T00:00:00Z"}')
    run('graph', repo, 'init-agents')
    assert 'entire brain brief' in run('graph', repo, 'agent-guide')
    setup.unlink()
    run('graph', repo, 'init-agents')
    assert 'entire brain brief' not in run('graph', repo, 'agent-guide')
    for state in ('malformed', 'unreadable'):
        setup.write_text('{' if state == 'malformed' else '{"schema_version":1}')
        if state == 'unreadable':
            setup.chmod(0)
        before = snapshot(repo)
        for tool in ('graph', 'brain'):
            run(tool, repo, 'init-agents', success=False)
            assert snapshot(repo) == before
        setup.chmod(0o600)
    assert not log.exists(), 'generation dispatched Entire or a plugin'
print('PASS: standalone, both activation orders, repeated generation, display parity, setup records, removal, byte stability, preservation, no dispatch')
EOF","max_output_tokens":1000}));

