package cli

import (
 "context"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
 "testing"

 "github.com/ashtom/entire-brain/internal/agentcoord"
)

// Exercise the actual setup writer and identity resolver, so the shared local
// reader cannot silently drift from Brain's persisted layout.
func TestAgentCoordinationActualSetupRecord(t *testing.T){
 for _,remote:=range []string{"","https://github.com/Team/Repo.git","git@gitlab.com:team/sub/repo.git","git@custom.example.com:team/repo.git","entire://server/gh/team/repo"}{t.Run(remote,func(t *testing.T){
 repo:=t.TempDir();env:=EntireEnv{PluginStateDir:t.TempDir(),PluginConfigDir:t.TempDir(),PluginDataDir:t.TempDir()}
 cmd:=exec.Command("git","init","-q",repo);if out,err:=cmd.CombinedOutput();err!=nil{t.Fatalf("git init: %s %v",out,err)}
 if remote!=""{if out,err:=exec.Command("git","-C",repo,"remote","add","origin",remote).CombinedOutput();err!=nil{t.Fatalf("git remote: %s %v",out,err)}}
 storage,err:=repoStoragePaths(context.Background(),ExecRunner{},env,repo);if err!=nil{t.Fatal(err)}
 if err:=writeSetupRecord(filepath.Dir(storage.HeadPath),setupRecord{SchemaVersion:setupBackfillStateVersion,Workspace:"fixture",Agent:"none"});err!=nil{t.Fatal(err)}
 root,err:=os.OpenRoot(repo);if err!=nil{t.Fatal(err)};root.Close()
 mode,err:=agentcoord.Resolve(repo,"graph",true,agentcoord.Dirs{StateDir:env.PluginStateDir,ConfigDir:env.PluginConfigDir},remote)
 if err!=nil||!mode.Graph||!mode.Brain{t.Fatalf("actual record not recognized: %+v %v",mode,err)}
 guide,err:=renderBrainAgentGuide(repo,Options{Env:env},false);if err!=nil||!strings.Contains(guide,"Use Brain"){t.Fatal(guide,err)}
 })}
}
EOF
