		path = m[2]
	} else if h, p, ok := strings.Cut(remote, "/"); ok && strings.Contains(h, ".") {
		host = strings.ToLower(h)
		path = p
	}
	if host == "" {
		repo, err := canonical(repo)
		if err != nil {
			return "", err
		}
		sum := sha256.Sum256([]byte(repo))
		base := component(filepath.Base(repo))
