package agentsetup

import (
 "bytes"
 "fmt"
 "os"
 "path/filepath"
 "strings"
)

// Existing names remain redirects for clients with explicit legacy imports.
// There is exactly one workflow body, in Path; generated files are not setup state.
const legacyRedirect = "Read the repository-root .entire/agent-guide.md for the current agent workflow.\n"

func migrateMarkers(content []byte)([]byte,error){
 for _,product:=range []string{"graph","brain"}{
  begin,end:=[]byte("<!-- entire-"+product+":begin -->"),[]byte("<!-- entire-"+product+":end -->")
  n,m:=bytes.Count(content,begin),bytes.Count(content,end)
  if n==0&&m==0{continue}
  a,b:=bytes.Index(content,begin),bytes.Index(content,end)
  if n!=1||m!=1||a>=b{return nil,fmt.Errorf("malformed Entire %s managed markers; repair before regenerating",product)}
  content=append(append([]byte{},content[:a]...),content[b+len(end):]...)
 }
 return content,nil
}

func preflightLegacy(root *os.Root, abs string)([]string,error){
 var names []string
 for _,name:=range []string{".entire/graph-agent.md",".entire/brain-agent.md"}{
  if err:=ensureContainedInRepo(root,name,filepath.Join(abs,name),false,".entire");err!=nil{return nil,err}
  info,err:=statContainedFile(root,name)
  if os.IsNotExist(err){continue};if err!=nil{return nil,err}
  if !info.Mode().IsRegular(){return nil,fmt.Errorf("%s is not a regular guide",name)}
  if err:=ensureNoSharedInode(root,name);err!=nil{return nil,err}
  for _,other:=range []string{"AGENTS.md","CLAUDE.md"}{
   target,err:=statContainedFile(root,other);if err==nil&&os.SameFile(info,target){return nil,fmt.Errorf("legacy guide %s aliases instruction file %s",name,other)}
  }
  // The canonical guide may already be the target of a legacy symlink.
  target,err:=statContainedFile(root,Path);if err==nil&&os.SameFile(info,target){continue}
  resolved,err:=resolveContainedName(root,name);if err!=nil{return nil,err}
  canonical,err:=resolveContainedName(root,Path);if err!=nil{return nil,err}
  if sameResolvedName(resolved,canonical){continue}
  names=append(names,name)
 }
 return names,nil
}
func writeLegacy(root *os.Root,names []string)error{
 for _,name:=range names {
  // Recheck identity after materializing the canonical guide and before writes.
  a,ea:=statContainedFile(root,name);b,eb:=statContainedFile(root,Path)
  if ea==nil&&eb==nil&&os.SameFile(a,b){continue}
  if err:=writeContainedFile(root,name,[]byte(legacyRedirect),0644);err!=nil{return err}
 }
 return nil
}

// Context gives explicit roots precedence over the host root; otherwise it finds
// the nearest Git root without invoking Git. Explicit roots can be non-Git projects.
func Context(explicit,host string)(string,error){
 p:=explicit;if p==""{p=host}
 if p!=""{return filepath.Abs(p)}
 p,err:=os.Getwd();if err!=nil{return "",err}
 for {
  _,err:=os.Lstat(filepath.Join(p,".git"));if err==nil{return p,nil};if !os.IsNotExist(err){return "",err}
  parent:=filepath.Dir(p);if parent==p{return "",nil};p=parent
 }
}

// safeKey permits only Brain's normalized repository-key components.
func safeKey(key string)bool{
 if key==""||strings.Contains(key,"\\"){return false}
 parts:=strings.Split(key,"/");if parts[0]=="workspaces"{return false}
 for _,p:=range parts{if p==""||p=="."||p==".."||cleanComponent(p)!=p{return false}}
 return true
}
EOF
