package agentsetup

import (
 "bytes"
 "context"
 "fmt"
 "io"
 "os"
 "os/exec"
 "regexp"
 "strings"
 "time"
)

// Options is a test seam and supports explicit Brain store roots. The normal
// path calls ONLY entire plugin list, never a plugin command to detect availability.
type Options struct {
 ListPlugins func()(string,error)
 StateDir,ConfigDir,DataDir string
}
func Preview(repo,product string,opts Options)(string,error){
 if product!="graph"&&product!="brain"{return "",fmt.Errorf("unknown product %q",product)}
 if repo==""{if product=="brain"{return BrainGuide(),nil};return GraphGuide,nil}
 list:=opts.ListPlugins;if list==nil{list=pluginList}
 raw,err:=list();if err!=nil{return "",fmt.Errorf("read entire plugin list: %w",err)}
 installed,err:=parsePluginList(raw);if err!=nil{return "",err}
 if product=="brain"{if installed["graph"]{return CombinedGuide,nil};return BrainGuide(),nil}
 if installed["brain"] {
  exists,err:=repositoryBrain(repo,opts);if err!=nil{return "",err}
  if exists{return CombinedGuide,nil}
 }
 return GraphGuide,nil
}

type limitedBuffer struct {bytes.Buffer; limit int}
func(b *limitedBuffer)Write(p []byte)(int,error){if b.Len()+len(p)>b.limit{return 0,fmt.Errorf("command output exceeds limit")};return b.Buffer.Write(p)}
func localCommand(repo,name string,args ...string)(string,error){
 ctx,cancel:=context.WithTimeout(context.Background(),15*time.Second);defer cancel()
 cmd:=exec.CommandContext(ctx,name,args...);cmd.Dir=repo
 cmd.Env=os.Environ()
 if name=="git"{
  cmd.Env=nil
  for _,v:=range os.Environ(){k,_,_:=strings.Cut(v,"=");if !strings.HasPrefix(k,"GIT_"){cmd.Env=append(cmd.Env,v)}}
  cmd.Env=append(cmd.Env,"GIT_CONFIG_NOSYSTEM=1","GIT_CONFIG_GLOBAL="+os.DevNull)
 }
 out,stderr:=&limitedBuffer{limit:1<<20},&limitedBuffer{limit:64<<10}
 cmd.Stdout=out;cmd.Stderr=stderr
 err:=cmd.Run();if err!=nil{return "",fmt.Errorf("%s: %w: %s",name,err,strings.TrimSpace(stderr.String()))}
 return out.String(),nil
}
func pluginList()(string,error){return localCommand("","entire","plugin","list")}
var pluginName=regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9_-]*$`)
func parsePluginList(raw string)(map[string]bool,error){
 installed:=map[string]bool{}
 lines:=strings.Split(strings.TrimSpace(raw),"\n")
 if len(lines)==2&&strings.HasPrefix(lines[0],"No plugins installed in ")&&strings.HasPrefix(lines[1],"Install one with 'entire plugin install "){return installed,nil}
 if len(lines)==0||!strings.HasPrefix(lines[0],"Managed plugin directory: "){return nil,fmt.Errorf("unrecognized entire plugin list output")}
 for _,line:=range lines[1:]{
  if strings.TrimSpace(line)==""{continue}
  fields:=strings.Fields(line)
  if !strings.HasPrefix(line,"  ")||len(fields)<2||!pluginName.MatchString(fields[0]){return nil,fmt.Errorf("malformed entire plugin list row")}
  if installed[fields[0]]{return nil,fmt.Errorf("duplicate plugin list entry %s",fields[0])}
  installed[fields[0]]=true
 }
 if len(installed)==0{return nil,fmt.Errorf("empty managed plugin listing")}
 return installed,nil
}
var _ io.Writer=(*limitedBuffer)(nil)
EOF","max_output_tokens":1000}));

