	for i := 0; ; i++ {
		sum := sha256.Sum256([]byte(host + ":" + strconv.Itoa(i)))
		slug := threeLetterSlug(sum)
		if _, ok := used[slug]; !ok {
			return slug
		}
	}
}

func threeLetterSlug(sum [sha256.Size]byte) string {
	n := int(sum[0])<<16 | int(sum[1])<<8 | int(sum[2])
	var b [3]byte
	for i := range b {
		b[i] = byte('a' + n%26)
		n /= 26
	}
	return string(b[:])
}

