func brainDirectory(explicit,override,xdg,fallback string)(string,error){
 dir:=os.Getenv(override);if dir==""{dir=explicit}
 if dir!=""{if !filepath.IsAbs(dir){return "",fmt.Errorf("%s must be absolute",override)};return dir,nil}
 if dir=os.Getenv(xdg);filepath.IsAbs(dir){return filepath.Join(dir,"entire"),nil}
 home,err:=os.UserHomeDir();if err!=nil{return "",err};return filepath.Join(home,fallback,"entire"),nil
}
func readRecord(dir,name string)([]byte,bool,error){
 root,err:=os.OpenRoot(dir);if os.IsNotExist(err){return nil,false,nil};if err!=nil{return nil,false,err};defer root.Close()
 var info os.FileInfo
 prefix:=""
 for _,part:=range strings.Split(filepath.ToSlash(name),"/"){
  prefix=filepath.Join(prefix,part);info,err=root.Lstat(prefix)
  if os.IsNotExist(err){return nil,false,nil};if err!=nil{return nil,false,err}
  if info.Mode()&os.ModeSymlink!=0{return nil,false,fmt.Errorf("setup state %s is a symbolic link",filepath.Join(dir,prefix))}
 }
 if !info.Mode().IsRegular()||info.Mode().Perm()&0444==0{return nil,false,fmt.Errorf("setup state %s is not a readable regular file",filepath.Join(dir,name))}
 f,err:=root.Open(name);if err!=nil{return nil,false,err};defer f.Close()
 info,err=f.Stat();if err!=nil{return nil,false,err};if !info.Mode().IsRegular(){return nil,false,fmt.Errorf("setup record is not regular")}
 const limit=16<<20
 data,err:=io.ReadAll(io.LimitReader(f,limit+1));if err!=nil{return nil,false,err};if len(data)>limit{return nil,false,fmt.Errorf("setup record exceeds size limit")}
 return data,true,nil
}
