func TestAgentGuideNameAndInstalledContent(t *testing.T) {
	opts := Options{Version: "test"}
	guide, err := execute(t, NewRootCommand(opts), "agent-guide")
	if err != nil {
		t.Fatal(err)
	}
	alias, err := execute(t, NewRootCommand(opts), "guide")
	if err != nil || alias != guide {
		t.Fatalf("guide alias differs: %v", err)
	}
	repo := t.TempDir()
	original := "# Team rules\nKeep these instructions.\n<!-- entire-graph:begin -->\nGraph rules\n<!-- entire-graph:end -->\n"
	for _, name := range []string{"AGENTS.md", "CLAUDE.md"} {
		if err := os.WriteFile(filepath.Join(repo, name), []byte(original), 0600); err != nil {
			t.Fatal(err)
		}
	}
	opts.Env.RepoRoot = repo
	out, err := execute(t, NewRootCommand(opts), "init-agents", "--json")
	if err != nil {
		t.Fatal(err)
	}
	var result struct {
		Changed []string `json:"changed_files"`
	}
	if err := json.Unmarshal([]byte(out), &result); err != nil || len(result.Changed) != 3 {
		t.Fatalf("install: %s / %v", out, err)
	}
	installed, err := os.ReadFile(filepath.Join(repo, brainAgentGuidePath))
	if err != nil || string(installed) != guide {
		t.Fatalf("installed guide differs: %v", err)
	}
	for _, name := range []string{"AGENTS.md", "CLAUDE.md"} {
		content, err := os.ReadFile(filepath.Join(repo, name))
		if err != nil {
			t.Fatal(err)
		}
		if !strings.HasPrefix(string(content), original) || strings.Count(string(content), brainAgentBegin) != 1 {
			t.Fatalf("lost or duplicated text: %s", content)
		}
		info, _ := os.Stat(filepath.Join(repo, name))
		if runtime.GOOS != "windows" && info.Mode().Perm() != 0600 {
			t.Fatalf("changed permissions: %v", info.Mode())
		}
	}
	changed, err := installBrainAgentGuide(repo)
	if err != nil || len(changed) != 0 {
		t.Fatalf("second install changed files: %v / %v", changed, err)
	}
}

func TestInitAgentsPreflightPreservesAllFiles(t *testing.T) {
	for _, invalid := range []string{
		brainAgentBegin, brainAgentEnd,
		brainAgentEnd + "\n" + brainAgentBegin,
		brainAgentBegin + "\n" + brainAgentBegin + "\n" + brainAgentEnd,
		"inline " + brainAgentBegin + "\n" + brainAgentEnd,
	} {
		t.Run(invalid, func(t *testing.T) {
			repo := t.TempDir()
			agents := filepath.Join(repo, "AGENTS.md")
			claude := filepath.Join(repo, "CLAUDE.md")
			os.WriteFile(agents, []byte("keep agents\n"), 0644)
			os.WriteFile(claude, []byte(invalid), 0644)
			if _, err := installBrainAgentGuide(repo); err == nil || !strings.Contains(err.Error(), "malformed") {
				t.Fatalf("accepted malformed markers: %v", err)
			}
			got, _ := os.ReadFile(agents)
			if string(got) != "keep agents\n" {
				t.Fatal("changed AGENTS.md before validation")
			}
			if _, err := os.Stat(filepath.Join(repo, ".entire")); !os.IsNotExist(err) {
				t.Fatal("created .entire before validation")
			}
		})
	}
}

func TestInitAgentsUpdatesOnlyManagedBlock(t *testing.T) {
	before, after := "user prefix\r\n", "user suffix\r\n"
	source := before + brainAgentBegin + "\r\nstale\r\n" + brainAgentEnd + "\r\n" + after
	pointer := brainAgentBegin + "\nnew guide\n" + brainAgentEnd + "\n"
	got, err := upsertBrainAgentPointer(source, pointer)
	if err != nil || got != before+pointer+after {
		t.Fatalf("upsert = %q, %v", got, err)
	}
}

func TestInitAgentsContainedAliasesAndEscapes(t *testing.T) {
	if runtime.GOOS == "windows" {
		t.Skip("symlink creation may require elevated privileges")
	}
	t.Run("shared instructions", func(t *testing.T) {
		repo := t.TempDir()
		os.WriteFile(filepath.Join(repo, "AGENTS.md"), []byte("shared instructions\n"), 0644)
		if err := os.Symlink("AGENTS.md", filepath.Join(repo, "CLAUDE.md")); err != nil {
			t.Fatal(err)
		}
		if _, err := installBrainAgentGuide(repo); err != nil {
			t.Fatal(err)
		}
		info, _ := os.Lstat(filepath.Join(repo, "CLAUDE.md"))
		if info.Mode()&os.ModeSymlink == 0 {
			t.Fatal("replaced instruction alias")
		}
		changed, err := installBrainAgentGuide(repo)
		if err != nil || len(changed) != 0 {
			t.Fatalf("not idempotent: %v / %v", changed, err)
		}
	})
	for _, target := range []string{"AGENTS.md", "CLAUDE.md", ".entire", brainAgentGuidePath} {
		t.Run(target, func(t *testing.T) {
			repo, outside := t.TempDir(), t.TempDir()
			external := filepath.Join(outside, "external.md")
			os.WriteFile(external, []byte("outside"), 0644)
			dest := external
			if target == ".entire" {
				dest = outside
			}
			if target == brainAgentGuidePath {
				os.Mkdir(filepath.Join(repo, ".entire"), 0755)
			}
			if err := os.Symlink(dest, filepath.Join(repo, target)); err != nil {
				t.Fatal(err)
			}
			if _, err := installBrainAgentGuide(repo); err == nil {
				t.Fatal("accepted escaping link")
			}
			content, _ := os.ReadFile(external)
			if string(content) != "outside" {
				t.Fatal("modified outside file")
			}
			if target != "AGENTS.md" {
				if _, err := os.Lstat(filepath.Join(repo, "AGENTS.md")); !os.IsNotExist(err) {
					t.Fatal("partial install")
				}
			}
		})
	}
	t.Run("guide aliases instructions", func(t *testing.T) {
		repo := t.TempDir()
		os.Mkdir(filepath.Join(repo, ".entire"), 0755)
		os.WriteFile(filepath.Join(repo, "AGENTS.md"), []byte("user rules"), 0644)
		os.Symlink("../AGENTS.md", filepath.Join(repo, brainAgentGuidePath))
		if _, err := installBrainAgentGuide(repo); err == nil {
			t.Fatal("accepted guide/instruction collision")
		}
		content, _ := os.ReadFile(filepath.Join(repo, "AGENTS.md"))
		if string(content) != "user rules" {
			t.Fatal("overwrote user rules")
		}
	})
	t.Run("external hardlink", func(t *testing.T) {
		repo, outside := t.TempDir(), filepath.Join(t.TempDir(), "rules")
		os.WriteFile(outside, []byte("keep"), 0644)
		if err := os.Link(outside, filepath.Join(repo, "AGENTS.md")); err != nil {
			t.Skip(err)
		}
		if _, err := installBrainAgentGuide(repo); err != nil {
			t.Fatal(err)
		}
		content, _ := os.ReadFile(outside)
		if string(content) != "keep" {
			t.Fatal("wrote through external hardlink")
		}
	})
}

func TestInitAgentsRejectsDirectoryAndOversizedFiles(t *testing.T) {
	for _, directory := range []bool{false, true} {
		repo := t.TempDir()
		name := filepath.Join(repo, "CLAUDE.md")
		if directory {
			os.Mkdir(name, 0755)
		} else {
			f, err := os.Create(name)
			if err != nil {
				t.Fatal(err)
			}
			if err := f.Truncate(brainInstructionLimit + 1); err != nil {
				t.Fatal(err)
			}
			f.Close()
		}
		if _, err := installBrainAgentGuide(repo); err == nil {
			t.Fatal("accepted invalid file")
		}
		if _, err := os.Stat(filepath.Join(repo, ".entire")); !os.IsNotExist(err) {
			t.Fatal("partial installation")
		}
	}
}

func TestCapabilitiesWithoutRepository(t *testing.T) {
	dir := t.TempDir()
	opts := Options{Version: "test-build", Env: EntireEnv{RepoRoot: filepath.Join(dir, "missing")}}
	out, err := execute(t, NewRootCommand(opts), "capabilities", "--json")
	if err != nil {
		t.Fatal(err)
	}
	var c brainCapabilities
	if err := json.Unmarshal([]byte(out), &c); err != nil {
		t.Fatal(err)
	}
	if c.Version != "test-build" || c.SchemaVersion != 1 || c.Build.BrainCGO != brainCGOBuild || c.Query.DefaultMode != "hybrid" {
		t.Fatalf("capabilities: %+v", c)
	}
	if len(c.Sources) != 4 {
		t.Fatalf("sources: %+v", c.Sources)
	}
	for _, source := range c.Sources {
		if source.Name == retrievalSourceConversation && (source.Default || !source.Experimental || source.SemanticCompiled != brainCGOBuild) {
			t.Fatalf("conversation availability overstated: %+v", source)
		}
	}
	entries, _ := os.ReadDir(dir)
	if len(entries) != 0 {
		t.Fatal("capabilities created repository state")
	}
	help, err := execute(t, NewRootCommand(opts), "--help")
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{"Set up your agent:", "init-agents", "agent-guide", "capabilities"} {
		if !strings.Contains(help, want) {
			t.Fatalf("help missing %q", want)
		}
	}
	for _, line := range strings.Split(help, "\n") {
		fields := strings.Fields(line)
		if len(fields) > 0 && fields[0] == "guide" {
			t.Fatal("old guide name remains in top-level list")
		}
	}
}
package cli

import (
	"crypto/rand"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/spf13/cobra"
)

const (
	brainAgentGuidePath   = ".entire/brain-agent.md"
	brainAgentBegin       = "<!-- entire-brain:begin -->"
	brainAgentEnd         = "<!-- entire-brain:end -->"
	brainInstructionLimit = 4 << 20
)

func newInitAgentsCommand(opts Options) *cobra.Command {
	var repo string
	var jsonOut bool
	cmd := &cobra.Command{
		Use:   "init-agents [path]",
		Short: "Install the coding-agent guide into AGENTS.md/CLAUDE.md",
		Long:  "Install .entire/brain-agent.md and managed pointer blocks in AGENTS.md and CLAUDE.md. Existing text outside Brain's markers is preserved. Re-running updates the guide without duplicate blocks. This does not build a brain or start services.",
		Args:  cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 1 {
				if cmd.Flags().Changed("repo") {
					return fmt.Errorf("supply either a path or --repo, not both")
				}
				repo = args[0]
			}
			if repo == "" {
				repo = opts.Env.RepoRoot
			}
			if repo == "" {
				repo = "."
			}
			changed, err := installBrainAgentGuide(repo)
			if err != nil {
				return fmt.Errorf("init-agents: %w", err)
			}
			if jsonOut {
				return json.NewEncoder(cmd.OutOrStdout()).Encode(map[string]any{"changed_files": changed})
			}
			if len(changed) == 0 {
				_, err = fmt.Fprintln(cmd.OutOrStdout(), "Agent instructions are already up to date.")
			} else {
				for _, path := range changed {
					if _, err = fmt.Fprintf(cmd.OutOrStdout(), "Updated %s\n", path); err != nil {
						return err
					}
				}
			}
			return err
		},
	}
	cmd.Flags().StringVar(&repo, "repo", "", "Project root (default: host repository or current directory)")
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit changed file paths as JSON")
	return cmd
}

type brainAgentFile struct {
	name    string
	data    []byte
	mode    os.FileMode
	changed bool
}

func installBrainAgentGuide(dir string) ([]string, error) {
	abs, err := filepath.Abs(dir)
	if err != nil {
		return nil, err
	}
	abs, err = filepath.EvalSymlinks(abs)
	if err != nil {
		return nil, err
	}
	root, err := os.OpenRoot(abs)
	if err != nil {
		return nil, err
	}
	defer root.Close()
	pointer := brainAgentBegin + "\n" +
		"Read .entire/brain-agent.md for this project's Entire Brain operating guide.\n" +
		"@.entire/brain-agent.md\n" + brainAgentEnd + "\n"
	var files []brainAgentFile
	seen := map[string]bool{}
	// Preflight every file before writing: malformed user markers and escaping
	// links must not leave a half-installed guide.
	for _, name := range []string{brainAgentGuidePath, "AGENTS.md", "CLAUDE.md"} {
		target, err := resolveBrainAgentTarget(root, abs, name)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", name, err)
		}
		if seen[target] {
			if target == files[0].name {
				return nil, fmt.Errorf("%s aliases the managed guide", name)
			}
			continue // AGENTS.md and CLAUDE.md may be relative symlink aliases.
		}
		seen[target] = true
		old, mode, err := readBrainInstruction(root, target)
		if err != nil {
			return nil, fmt.Errorf("%s: %w", name, err)
		}
		data := brainAgentGuide
		if name != brainAgentGuidePath {
			data, err = upsertBrainAgentPointer(string(old), pointer)
			if err != nil {
				return nil, fmt.Errorf("%s: %w", name, err)
			}
		}
		files = append(files, brainAgentFile{target, []byte(data), mode, string(old) != data})
	}
	changed := []string{}
	for _, file := range files {
		if !file.changed {
			continue
		}
		if err := root.MkdirAll(filepath.Dir(file.name), 0755); err != nil {
			return changed, err
		}
		if err := writeBrainAgentFile(root, file); err != nil {
			return changed, fmt.Errorf("%s: %w", file.name, err)
		}
		changed = append(changed, file.name)
	}
	return changed, nil
}

// Resolve existing links, including instruction aliases, to repository-relative
// targets. All reads and writes remain rooted, even if a link changes later.
func resolveBrainAgentTarget(root *os.Root, abs, name string) (string, error) {
	pending := strings.Split(filepath.ToSlash(name), "/")
	resolved := ""
	links := 0
	for len(pending) > 0 {
		part := pending[0]
		pending = pending[1:]
		if part == "" || part == "." {
			continue
		}
		if part == ".." {
			if resolved == "" {
				return "", fmt.Errorf("path escapes the project")
			}
			resolved = filepath.Dir(resolved)
			if resolved == "." {
				resolved = ""
			}
			continue
		}
		candidate := filepath.Join(resolved, part)
		info, err := root.Lstat(candidate)
		if errors.Is(err, os.ErrNotExist) {
			// Only the .entire directory and final files may be created.
			if len(pending) > 0 && candidate != ".entire" {
				return "", err
			}
			resolved = candidate
			continue
		}
		if err != nil {
			return "", err
		}
		if info.Mode()&os.ModeSymlink != 0 {
			links++
			if links > 40 {
				return "", fmt.Errorf("too many symbolic links")
			}
			target, err := root.Readlink(candidate)
			if err != nil {
				return "", err
			}
			if filepath.IsAbs(target) {
				target, err = filepath.Rel(abs, target)
				if err != nil || !filepath.IsLocal(target) {
					return "", fmt.Errorf("link escapes the project")
				}
				resolved = ""
			}
			pending = append(strings.Split(filepath.ToSlash(target), "/"), pending...)
			continue
		}
		if len(pending) > 0 && !info.IsDir() {
			return "", fmt.Errorf("%s is not a directory", candidate)
		}
		resolved = candidate
	}
	if !filepath.IsLocal(resolved) {
		return "", fmt.Errorf("path escapes the project")
	}
	return resolved, nil
}

func readBrainInstruction(root *os.Root, name string) ([]byte, os.FileMode, error) {
	// Check type before opening so a FIFO cannot block the installer.
	info, err := root.Lstat(name)
	if errors.Is(err, os.ErrNotExist) {
		return nil, 0644, nil
	}
	if err != nil {
		return nil, 0, err
	}
	if !info.Mode().IsRegular() {
		return nil, 0, fmt.Errorf("expected a regular file")
	}
	f, err := root.Open(name)
	if err != nil {
		return nil, 0, err
	}
	defer f.Close()
	info, err = f.Stat()
	if err != nil {
		return nil, 0, err
	}
	if !info.Mode().IsRegular() {
		return nil, 0, fmt.Errorf("expected a regular file")
	}
	data, err := io.ReadAll(io.LimitReader(f, brainInstructionLimit+1))
	if err != nil {
		return nil, 0, err
	}
	if len(data) > brainInstructionLimit {
		return nil, 0, fmt.Errorf("instruction file exceeds 4 MiB")
	}
	return data, info.Mode().Perm(), nil
}

func upsertBrainAgentPointer(text, pointer string) (string, error) {
	begins, ends := strings.Count(text, brainAgentBegin), strings.Count(text, brainAgentEnd)
	if begins == 0 && ends == 0 {
		sep := ""
		if text != "" {
			if !strings.HasSuffix(text, "\n") {
				sep = "\n"
			}
			sep += "\n"
		}
		return text + sep + pointer, nil
	}
	begin, end := strings.Index(text, brainAgentBegin), strings.Index(text, brainAgentEnd)
	wholeLine := func(index int, marker string) bool {
		if index < 0 || (index > 0 && text[index-1] != '\n') {
			return false
		}
		rest := text[index+len(marker):]
		return rest == "" || strings.HasPrefix(rest, "\n") || strings.HasPrefix(rest, "\r\n")
	}
	if begins != 1 || ends != 1 || begin >= end || !wholeLine(begin, brainAgentBegin) || !wholeLine(end, brainAgentEnd) {
		return "", fmt.Errorf("malformed Entire Brain markers; back up the file and repair the marked block before rerunning init-agents")
	}
	end += len(brainAgentEnd)
	if strings.HasPrefix(text[end:], "\r\n") {
		end += 2
	} else if strings.HasPrefix(text[end:], "\n") {
		end++
	}
	return text[:begin] + pointer + text[end:], nil
}

// Replacing directory entries atomically avoids truncating user text and avoids
// writing through hard links into files outside the project.
func writeBrainAgentFile(root *os.Root, file brainAgentFile) error {
	temp := filepath.Join(filepath.Dir(file.name), ".brain-agent-"+rand.Text()+".tmp")
	f, err := root.OpenFile(temp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, file.mode)
	if err != nil {
		return err
	}
	defer root.Remove(temp)
	if err = f.Chmod(file.mode); err != nil {
		f.Close()
		return err
	}
	if _, err = f.Write(file.data); err == nil {
		err = f.Sync()
	}
	closeErr := f.Close()
	if err != nil {
		return err
	}
	if closeErr != nil {
		return closeErr
	}
	return root.Rename(temp, file.name)
}

